import React, { useState } from 'react';
import api from '../api';

function Signup() {
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    passwordHash: '',
    firstName: '',
    lastName: '',
    phone: '',
    role: 'USER'
  });

  const [message, setMessage] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSignup = async (e) => {
    e.preventDefault();

    try {
      await api.post('/users', formData); // removed unused `response`
      setMessage('User registered successfully!');
    } catch (error) {
      if (error.response?.data) {
        setMessage(error.response.data);
      } else {
        setMessage('Error registering user');
      }
    }
  };

  return (
    <div>
      <h2>Signup</h2>
      <form onSubmit={handleSignup}>
        <input name="username" placeholder="Username" onChange={handleChange} required /><br />
        <input name="email" type="email" placeholder="Email" onChange={handleChange} required /><br />
        <input name="passwordHash" type="password" placeholder="Password" onChange={handleChange} required /><br />
        <input name="firstName" placeholder="First Name" onChange={handleChange} required /><br />
        <input name="lastName" placeholder="Last Name" onChange={handleChange} required /><br />
        <input name="phone" placeholder="Phone" onChange={handleChange} /><br />
        <select name="role" onChange={handleChange}>
          <option value="USER">USER</option>
          <option value="SECURITY">SECURITY</option>
          <option value="FACILITY_MANAGER">FACILITY_MANAGER</option>
          <option value="SYSTEM_ADMIN">SYSTEM_ADMIN</option>
        </select><br />
        <button type="submit">Register</button>
      </form>
      <p>{message}</p>
    </div>
  );
}

export default Signup;
